        G[k]=[[int(x) for x in r] for r in rows]
def f(gi):
    g=[r[:] for r in gi]; H,W=len(g),len(g[0])
    # templates from demo: {1,2}->[1,6,2]; {4,8}->[4,3,7,8]; assume 6,7 share [4,5,6,7]; 9->[9,5,3,4]
    tmpl={1:(1,6,2),2:(1,6,2),4:(4,3,7,8),8:(4,3,7,8),6:(4,5,6,7),7:(4,5,6,7),9:(9,5,3,4)}
    for i in range(H):
        j=0
        while j<W:
            if g[i][j]==0: j+=1; continue
            k=j
            while k<W and g[i][k]==g[i][j]: k+=1
            if k-j==1:
                c=g[i][j]; s=tmpl.get(c)
                if s is None: j=k; continue
                p=s.index(c); plen=len(s)
                roomL=j           # free cells left of seed
                roomR=W-1-j       # free cells right of seed
                cands=[]
                if roomL>=plen-1: cands.append(('L',j-p))
                if roomR>=plen-1: cands.append(('R',j))
                if not cands: j=k; continue
                cands.sort(key=lambda x:-x[1][0] if False else -(x[0]=='L'))
                # pick side with more room; tie -> L
                st=cands[0][1]
                for q,v in enumerate(s):
                    idx=st+q
                    if 0<=idx<W: g[i][idx]=v
            j=k
    return g
print(f(G['Demo pair 3 input'])==G['Demo pair 3 output'])
out=f(G['Test input'])
for r in out: print(''.join('.' if v==0 else str(v) for v in r))
